import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Flavor {
  id: number;
  name: string;
  description: string;
  color: string;
}

export interface Pack {
  id: string;
  name: string;
  price: string;
  quantity: string;
  features: string[];
  isPopular?: boolean;
}

export interface OrderFormData {
  firstName: string;
  lastName: string;
  phone: string;
  pack: string;
  quantity: number;
  location: string;
}

import React, { useState, useEffect } from 'react';
import { Menu, X } from 'lucide-react';

const Header: React.FC = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    setIsMobileMenuOpen(false);
    const element = document.getElementById(id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <header 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        isScrolled ? 'bg-cream/95 backdrop-blur-md shadow-sm py-3' : 'bg-transparent py-5'
      }`}
    >
      <div className="container mx-auto px-4 md:px-6 flex items-center justify-between">
        {/* Logo */}
        <div className="flex items-center gap-2 cursor-pointer" onClick={() => scrollToSection('hero')}>
          <div className="text-2xl md:text-3xl font-display font-bold text-forest tracking-tight">
            Nic's <span className="text-terracotta">Manioc</span>
          </div>
        </div>

        {/* Desktop Nav */}
        <nav className="hidden md:flex items-center gap-8 font-medium text-forest">
          <button onClick={() => scrollToSection('flavors')} className="hover:text-terracotta transition-colors">Saveurs</button>
          <button onClick={() => scrollToSection('story')} className="hover:text-terracotta transition-colors">L'Histoire</button>
          <button onClick={() => scrollToSection('packs')} className="hover:text-terracotta transition-colors">Tarifs</button>
          <button 
            onClick={() => scrollToSection('order')} 
            className="bg-forest text-cream px-6 py-2.5 rounded-full font-semibold hover:bg-terracotta transition-all shadow-lg hover:shadow-terracotta/30 transform hover:-translate-y-0.5"
          >
            Goûter l'Afrique
          </button>
        </nav>

        {/* Mobile Menu Toggle */}
        <button 
          className="md:hidden text-forest"
          onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
        >
          {isMobileMenuOpen ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {/* Mobile Nav */}
      {isMobileMenuOpen && (
        <div className="md:hidden absolute top-full left-0 right-0 bg-cream shadow-xl border-t border-forest/10 p-6 flex flex-col gap-4 items-center animate-fadeIn">
          <button onClick={() => scrollToSection('flavors')} className="text-lg font-medium text-forest">Saveurs</button>
          <button onClick={() => scrollToSection('story')} className="text-lg font-medium text-forest">L'Histoire</button>
          <button onClick={() => scrollToSection('packs')} className="text-lg font-medium text-forest">Tarifs</button>
          <button 
            onClick={() => scrollToSection('order')} 
            className="bg-terracotta text-white w-full py-3 rounded-xl font-bold mt-2"
          >
            Commander Maintenant
          </button>
        </div>
      )}
    </header>
  );
};

export default Header;

import React from 'react';
import { FLAVORS } from '../constants';

const FlavorSection: React.FC = () => {
  return (
    <section id="flavors" className="py-20 px-4 bg-white/50">
      <div className="container mx-auto">
        <div className="text-center mb-16">
          <h2 className="text-4xl md:text-5xl font-display font-bold text-forest mb-4">Le Tour d'Afrique en <span className="text-ochre">10 Escales</span></h2>
          <p className="text-forest/70 max-w-2xl mx-auto">
            Chaque sachet est une invitation au voyage. Nous avons sélectionné les meilleures épices pour accompagner la douceur du manioc.
          </p>
        </div>

        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 md:gap-6">
          {FLAVORS.map((flavor) => (
            <div 
              key={flavor.id} 
              className="group bg-white p-6 rounded-2xl shadow-sm hover:shadow-xl transition-all duration-300 border border-forest/5 hover:-translate-y-1 flex flex-col items-center text-center h-full"
            >
              <div className={`w-16 h-16 ${flavor.color} rounded-full mb-4 flex items-center justify-center text-2xl group-hover:scale-110 transition-transform`}>
                {/* Visual abstraction of spice/flavor using emoji or minimal div */}
                {['🌶️','🥣','🍋','🔥','🥜','🍗','🍛','🌿','🪵','🧂'][flavor.id - 1]}
              </div>
              <h3 className="font-display font-bold text-lg text-forest mb-2">{flavor.name}</h3>
              <p className="text-sm text-forest/70 leading-snug">{flavor.description}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default FlavorSection;

import React from 'react';
import { Check } from 'lucide-react';
import { PACKS } from '../constants';

const PricingSection: React.FC = () => {
  const scrollToOrder = (packId: string) => {
    // This is a simple implementation. In a real app, this might update a context or URL param
    const orderSection = document.getElementById('order');
    if (orderSection) {
      orderSection.scrollIntoView({ behavior: 'smooth' });
      // Dispatch a custom event or use context to pre-select the pack would be better in a larger app
      // For this single file scope, we rely on the user selecting it manually or basic focus
    }
  };

  return (
    <section id="packs" className="py-24 px-4 bg-cream">
      <div className="container mx-auto">
        <div className="text-center mb-16">
          <h2 className="text-4xl md:text-5xl font-display font-bold text-forest mb-4">Nos Packs Gourmands</h2>
          <p className="text-forest/70">Choisissez la formule qui convient à votre appétit.</p>
        </div>

        <div className="flex flex-col md:flex-row justify-center items-stretch gap-8 max-w-4xl mx-auto">
          {PACKS.map((pack) => (
            <div 
              key={pack.id}
              className={`flex-1 rounded-3xl p-8 relative flex flex-col ${
                pack.isPopular 
                  ? 'bg-forest text-white shadow-2xl scale-105 z-10 border-2 border-ochre' 
                  : 'bg-white text-forest shadow-xl border border-gray-100'
              }`}
            >
              {pack.isPopular && (
                <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-1/2 bg-terracotta text-white px-4 py-1 rounded-full text-sm font-bold uppercase tracking-wide shadow-md">
                  Best Seller
                </div>
              )}

              <div className="mb-6">
                <h3 className={`text-2xl font-display font-bold mb-2 ${pack.isPopular ? 'text-white' : 'text-forest'}`}>
                  {pack.name}
                </h3>
                <div className="flex items-baseline gap-1">
                  <span className={`text-4xl font-bold ${pack.isPopular ? 'text-ochre' : 'text-terracotta'}`}>
                    {pack.price}
                  </span>
                </div>
                <p className={`mt-2 text-sm opacity-80 ${pack.isPopular ? 'text-gray-300' : 'text-gray-500'}`}>
                  {pack.quantity}
                </p>
              </div>

              <ul className="space-y-4 mb-8 flex-1">
                {pack.features.map((feature, idx) => (
                  <li key={idx} className="flex items-center gap-3">
                    <div className={`p-1 rounded-full ${pack.isPopular ? 'bg-white/20' : 'bg-forest/10'}`}>
                      <Check size={14} className={pack.isPopular ? 'text-ochre' : 'text-forest'} />
                    </div>
                    <span className={pack.isPopular ? 'text-gray-100' : 'text-gray-700'}>{feature}</span>
                  </li>
                ))}
              </ul>

              <button
                onClick={() => scrollToOrder(pack.id)}
                className={`w-full py-4 rounded-xl font-bold transition-all ${
                  pack.isPopular 
                    ? 'bg-ochre text-forest hover:bg-white' 
                    : 'bg-forest text-white hover:bg-terracotta'
                }`}
              >
                Je choisis ce pack
              </button>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default PricingSection;

import React, { useState } from 'react';
import { PACKS } from '../constants';
import { OrderFormData } from '../types';
import { Send, CheckCircle } from 'lucide-react';

const OrderForm: React.FC = () => {
  const [formData, setFormData] = useState<OrderFormData>({
    firstName: '',
    lastName: '',
    phone: '',
    pack: 'decouverte',
    quantity: 1,
    location: ''
  });

  const [isSubmitted, setIsSubmitted] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Simulate API call
    setTimeout(() => {
      setIsSubmitted(true);
      // Reset form eventually? 
      // setFormData(...)
    }, 800);
  };

  return (
    <section id="order" className="py-24 px-4 bg-gradient-to-br from-ochre/10 to-terracotta/10">
      <div className="container mx-auto max-w-3xl">

        <div className="bg-white rounded-3xl shadow-xl overflow-hidden">
          <div className="bg-forest p-8 text-center">
            <h2 className="text-3xl font-display font-bold text-white mb-2">Passez Commande</h2>
            <p className="text-white/70">Remplissez le formulaire, on s'occupe du reste.</p>
          </div>

          <div className="p-8 md:p-12">
            {isSubmitted ? (
              <div className="flex flex-col items-center justify-center text-center py-10 animate-fadeIn">
                <div className="w-24 h-24 bg-green-100 rounded-full flex items-center justify-center mb-6 text-green-600">
                  <CheckCircle size={48} />
                </div>
                <h3 className="text-3xl font-display font-bold text-forest mb-4">C'est dans la boîte !</h3>
                <p className="text-lg text-gray-600 max-w-md mx-auto">
                  Merci {formData.firstName} ! Votre commande a bien été reçue. Notre équipe va vous contacter au {formData.phone} très rapidement pour la livraison.
                </p>
                <button 
                  onClick={() => setIsSubmitted(false)}
                  className="mt-8 text-terracotta font-semibold underline hover:text-forest"
                >
                  Passer une autre commande
                </button>
              </div>
            ) : (
              <form onSubmit={handleSubmit} className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label htmlFor="firstName" className="text-sm font-semibold text-forest uppercase tracking-wide">Prénom</label>
                    <input
                      required
                      type="text"
                      id="firstName"
                      name="firstName"
                      value={formData.firstName}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50"
                      placeholder="Nic"
                    />
                  </div>
                  <div className="space-y-2">
                    <label htmlFor="lastName" className="text-sm font-semibold text-forest uppercase tracking-wide">Nom</label>
                    <input
                      required
                      type="text"
                      id="lastName"
                      name="lastName"
                      value={formData.lastName}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50"
                      placeholder="Manioc"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label htmlFor="phone" className="text-sm font-semibold text-forest uppercase tracking-wide">Téléphone / WhatsApp</label>
                  <input
                    required
                    type="tel"
                    id="phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50"
                    placeholder="+229 97 00 00 00"
                  />
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div className="space-y-2">
                    <label htmlFor="pack" className="text-sm font-semibold text-forest uppercase tracking-wide">Choix du Pack</label>
                    <select
                      id="pack"
                      name="pack"
                      value={formData.pack}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50 appearance-none"
                    >
                      {PACKS.map(pack => (
                        <option key={pack.id} value={pack.id}>
                          {pack.name} - {pack.price}
                        </option>
                      ))}
                    </select>
                  </div>
                  <div className="space-y-2">
                    <label htmlFor="quantity" className="text-sm font-semibold text-forest uppercase tracking-wide">Quantité</label>
                    <input
                      required
                      type="number"
                      min="1"
                      max="50"
                      id="quantity"
                      name="quantity"
                      value={formData.quantity}
                      onChange={handleChange}
                      className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50"
                    />
                  </div>
                </div>

                <div className="space-y-2">
                  <label htmlFor="location" className="text-sm font-semibold text-forest uppercase tracking-wide">Lieu de livraison</label>
                  <input
                    required
                    type="text"
                    id="location"
                    name="location"
                    value={formData.location}
                    onChange={handleChange}
                    className="w-full px-4 py-3 rounded-xl border-2 border-gray-100 focus:border-terracotta focus:ring-0 outline-none transition-colors bg-gray-50"
                    placeholder="Quartier, Ville, Indication..."
                  />
                </div>

                <button 
                  type="submit"
                  className="w-full bg-terracotta text-white font-bold text-lg py-4 rounded-xl hover:bg-forest transition-colors shadow-lg shadow-terracotta/30 flex items-center justify-center gap-2 mt-4"
                >
                  <Send size={20} />
                  Valider ma commande
                </button>
              </form>
            )}
          </div>
        </div>
      </div>
    </section>
  );
};

export default OrderForm;

import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import FlavorSection from './components/FlavorSection';
import PricingSection from './components/PricingSection';
import StorySection from './components/StorySection';
import OrderForm from './components/OrderForm';
import Footer from './components/Footer';

function App() {
  return (
    <div className="min-h-screen bg-cream font-sans selection:bg-terracotta selection:text-white">
      <Header />
      <main>
        <Hero />
        <FlavorSection />
        <PricingSection />
        <StorySection />
        <OrderForm />
      </main>
      <Footer />
    </div>
  );
}

export default App;
